    ('栋', '新建的小区里有十栋现代化的住宅楼。', 'xà ngang, tòa nhà', 'dòng', '新建的小区里有十栋现代化的住宅楼。', 'xà ngang, tòa nhà', 'dòng', 'Xīn jiàn de xiǎo qū lǐ yǒu shí dòng xiàn dài huà de zhù zhái lóu.', 'Khu chung cư mới xây có mười tòa nhà dân cư hiện đại.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0e1457401a5a815ff0fbe6fd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f41c4aead06cc8765e9cf711.mp3'),
    ('杜绝', '为了杜绝浪费，工厂采取了严格的节能措施。', 'chắn đứng (tham ô, lãng phí….)', 'dù jué', '为了杜绝浪费，工厂采取了严格的节能措施。', 'chắn đứng (tham ô, lãng phí….)', 'dù jué', 'Wèi le dù jué làng fèi, gōng chǎng cǎi qǔ le yán gé de jié néng cuò shī.', 'Để chặn đứng lãng phí, nhà máy đã áp dụng các biện pháp tiết kiệm năng lượng nghiêm ngặt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-5cad1fcb6495862ba6edeb3a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e1afc7764c0224bb2622bf9f.mp3'),
    ('断绝', '他们因误会而断绝了多年的友谊。', 'đoạn tuyệt, cắt đứt (mối quan hệ)', 'duàn jué', '他们因误会而断绝了多年的友谊。', 'đoạn tuyệt, cắt đứt (mối quan hệ)', 'duàn jué', 'Tā men yīn wù huì ér duàn jué le duō nián de yǒu yì.', 'Vì hiểu lầm mà họ đã cắt đứt tình bạn nhiều năm trời.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c9f3d9bde30cfbe7be9d8e4d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-2e38b2f524ff51083793c915.mp3'),
    ('断定', '根据现有证据，警方断定嫌疑人是罪犯。', 'dám chắc', 'duàn dìng', '根据现有证据，警方断定嫌疑人是罪犯。', 'dám chắc', 'duàn dìng', 'Gēn jù xiàn yǒu zhèng jù, jǐng fāng duàn dìng xián yí rén shì zuì fàn.', 'Dựa trên bằng chứng hiện có, cảnh sát dám chắc nghi phạm là tội phạm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-38578ca391459c3415563720.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-6e4b61f05afbb9cd1a6027ac.mp3'),
    ('斗争', '工人们为了权益展开了长期的斗争。', 'đấu tranh', 'dòu zhēng', '工人们为了权益展开了长期的斗争。', 'đấu tranh', 'dòu zhēng', 'Gōng rén men wèi le quán yì zhǎn kāi le cháng qī de dòu zhēng.', 'Công nhân đã tiến hành cuộc đấu tranh dài hạn vì quyền lợi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-57cd33d54f8bba9adbceaa2f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-400cd4b2ce0d6f4e3169f965.mp3'),
    ('敌视', '双方因为利益冲突而产生了敌视情绪。', 'thù địch', 'dí shì', '双方因为利益冲突而产生了敌视情绪。', 'thù địch', 'dí shì', 'Shuāng fāng yīn wèi lì yì chōng tū ér chǎn shēng le dí shì qíng xù.', 'Hai bên nảy sinh cảm xúc thù địch do xung đột lợi ích.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c8c9d8ed490cb09fa51cc30d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-6c0bd2e23fd3c951ff2d179e.mp3'),
    ('搭配', '这件衣服和那双鞋子搭配得非常协调。', 'kết hợp', 'dā pèi', '这件衣服和那双鞋子搭配得非常协调。', 'kết hợp', 'dā pèi', 'Zhè jiàn yī fú hé nà shuāng xié zi dā pèi dé fēi cháng xié tiáo.', 'Chiếc áo này kết hợp với đôi giày kia rất hài hòa.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-1e97638b1609801a8ae33969.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-44c967fc9e20146a815a9f7d.mp3'),
    ('搭档', '这次比赛中，他们作为搭档表现得非常出色。', 'hợp tác, người hợp tác', 'dā dàng', '这次比赛中，他们作为搭档表现得非常出色。', 'hợp tác, người hợp tác', 'dā dàng', 'Zhè cì bǐ sài zhōng, tā men zuò wéi dā dàng biǎo xiàn dé fēi cháng chū sè.', 'Trong cuộc thi lần này, họ thể hiện rất xuất sắc với tư cách là người hợp tác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0a9a0d33090369acf194ec96.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f3912f6bec20205320bfe097.mp3'),
    ('搭', '他用木头搭了一个简易的房子。', 'mắc, vắt, đắp, đáp', 'dā', '他用木头搭了一个简易的房子。', 'mắc, vắt, đắp, đáp', 'dā', 'Tā yòng mù tóu dā le yī gè jiǎn yì de fáng zi.', 'Anh ta dùng gỗ để đắp một ngôi nhà đơn giản.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-bee93d5f704c634e43c52620.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f4a0ecb7355ee70fe2f9bb6e.mp3')
)
update public.template_cards as card
set
  pinyin = repaired.pinyin,
  meaning_vi = repaired.meaning_vi,
  example_cn = repaired.example_cn,
  example_pinyin = repaired.example_pinyin,
  example_vi = repaired.example_vi,
  word_audio_url = repaired.word_audio_url,
  sentence_audio_url = repaired.sentence_audio_url
from public.template_decks as deck,
  repaired_hsk as repaired
where card.template_deck_id = deck.id
  and deck.slug = 'hsk6-co-ban'
  and card.chinese = repaired.chinese;

with repaired_hsk (
  chinese,
  original_example_cn,
  original_meaning_vi,
  original_pinyin,
